-- Independent birth-exact-link-a2-v1 owner-side ACL, never runtime provisioning.
-- Fixed columns derive from original 001--022 + B-P1 and the A2 relation material.
-- APP management/customer-finance DML outside the seven protected original
-- relations and original PB Commander DML stay at their established baseline.
-- No table-wide grant, live column discovery or direct trigger EXECUTE is added.
DO $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE oid={{MONI_APP_OID}}::oid AND rolname={{MONI_APP_TEXT}} AND rolcanlogin AND NOT rolsuper AND NOT rolinherit AND NOT rolcreatedb AND NOT rolcreaterole AND NOT rolreplication AND NOT rolbypassrls)
  OR NOT EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE oid={{MONI_WRITER_OID}}::oid AND rolname={{MONI_WRITER_TEXT}} AND NOT rolcanlogin AND NOT rolsuper AND NOT rolinherit AND NOT rolcreatedb AND NOT rolcreaterole AND NOT rolreplication AND NOT rolbypassrls)
  OR EXISTS(SELECT 1 FROM pg_catalog.pg_auth_members WHERE roleid IN ({{MONI_APP_OID}}::oid,{{MONI_WRITER_OID}}::oid) OR member IN ({{MONI_APP_OID}}::oid,{{MONI_WRITER_OID}}::oid)) THEN
  RAISE EXCEPTION 'procurement_execution_protocol' USING ERRCODE='PP903';
 END IF;
END $$;
